function updateClock(){let d=new Date(),days=['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'],months=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];let de=document.getElementById('uiDate'),ti=document.getElementById('uiTime');if(de)de.textContent=days[d.getDay()]+', '+d.getDate()+'. '+months[d.getMonth()]+' '+d.getFullYear();if(ti)ti.textContent=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}updateClock();setInterval(updateClock,30000);
let jobs=[];const q=s=>document.querySelector(s);let currentNoteId=0;let editReturnView='all';let appSettings={regular_slots:8,buffer_slots:2,pickup_message:'',closed_dates:{},enabled_radios:['1live','jamfm','bollerwagen','bigfm','swr3','wdr4','bob','sunshine']};async function api(path,opt={}){let r=await fetch(path,opt);let j=await r.json();if(!r.ok)throw Error(j.error||'Fehler');return j}async function loadAppSettings(){try{appSettings=await api('/api/app-settings');applyRadioVisibility()}catch(e){}}
function applyRadioVisibility(){RADIO_STATIONS.forEach(s=>{let el=q('#radioLink'+s);if(el)el.classList.toggle('hidden',!appSettings.enabled_radios.includes(s))})}
function renderRadioToggles(){q('#radioToggleList').innerHTML=RADIO_STATIONS.map(s=>`<label style="flex-direction:row;align-items:center;gap:6px;font-weight:400"><input type="checkbox" value="${s}" ${appSettings.enabled_radios.includes(s)?'checked':''}> ${esc(RADIO_NAMES[s])}</label>`).join('')}
async function saveRadioSettings(){let enabled=[...document.querySelectorAll('#radioToggleList input:checked')].map(i=>i.value);appSettings=await api('/api/app-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled_radios:enabled})});applyRadioVisibility();alert('Gespeichert.')}
function renderClosedDates(){let entries=Object.entries(appSettings.closed_dates||{}).sort();q('#closedDatesList').innerHTML=entries.length?entries.map(([d,label])=>`<div class="backupRow"><span class="backupMeta">${fmt(d)}${label?' · '+esc(label):''}</span><button type="button" class="btn danger" onclick="removeClosedDate('${d}')">Entfernen</button></div>`).join(''):'<p class="muted">Keine zusätzlichen Schließtage.</p>'}
async function addClosedDate(){let d=q('#closedDateInput').value;if(!d){alert('Bitte Datum wählen.');return}let label=q('#closedDateLabel').value.trim()||'Betriebsurlaub';let updated={...appSettings.closed_dates,[d]:label};appSettings=await api('/api/app-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({closed_dates:updated})});q('#closedDateInput').value='';q('#closedDateLabel').value='';renderClosedDates()}
async function removeClosedDate(d){let updated={...appSettings.closed_dates};delete updated[d];appSettings=await api('/api/app-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({closed_dates:updated})});renderClosedDates()}async function load(){jobs=await api('/api/jobs');renderDash()}function setNavActive(label){document.querySelectorAll('.sideNav button').forEach(b=>b.classList.toggle('active',!!label&&b.textContent.includes(label)))}function show(id){['dash','all','edit','intake','printview','newchoice','preplan','onlinezulassung','onlineabmeldung','wunschkennzeichen','terminreservieren','onlineauskunft','webseiten','help','praege','manualpdfs','manualpdfcat','personal','customers','customerEdit','settings'].forEach(x=>q('#'+x).classList.toggle('hidden',x!==id));let nav={dash:'Heute im StVA',all:'Alle Aufträge',onlinezulassung:'Online Zulassung',onlineabmeldung:'Online Abmeldung',wunschkennzeichen:'Wunschkennzeichen reservieren',terminreservieren:'Termin reservieren',onlineauskunft:'Online Auskunft Fahrzeugbriefe',manualpdfs:'Formulare',manualpdfcat:'Formulare',webseiten:'Web Seiten',help:'Hilfe',praege:'Hilfe',personal:'Notizen',customers:'Kundendatenbank',settings:'Einstellungen'};if(nav[id])setNavActive(nav[id]);let wt={dash:'Arbeitszentrale',all:'Auftragsübersicht',onlinezulassung:'Online Zulassung',onlineabmeldung:'Online Abmeldung',wunschkennzeichen:'Wunschkennzeichen reservieren',terminreservieren:'Termin reservieren',onlineauskunft:'Online Auskunft Fahrzeugbriefe',manualpdfs:'Formulare',manualpdfcat:'Formulare',webseiten:'Web Seiten',help:'Hilfe',praege:'Arbeitsanweisung Schilder',newchoice:'Neuer Auftrag',preplan:'Termin vorplanen',intake:'Kundenannahme',edit:'Auftrag bearbeiten',printview:'Druckpaket',personal:'Notizen',customers:'Kundendatenbank',customerEdit:'Kunde',settings:'Einstellungen'};if(q('#workspaceTitle'))q('#workspaceTitle').textContent='';if(id==='all')renderAll();if(id==='dash')load()}function openExternal(url){window.open(url,'_blank','noopener,noreferrer')}
const RADIO_STATIONS=['1live','jamfm','bollerwagen','bigfm','swr3','wdr4','bob','sunshine'];
const RADIO_NAMES={'1live':'1LIVE','jamfm':'JAM FM','bollerwagen':'Radio Bollerwagen','bigfm':'bigFM','swr3':'SWR3','wdr4':'WDR4','bob':'Radio Bob','sunshine':'Sunshine Live'};
let radioNowPlayingTimer=null;
function toggleRadio(station){let a=q('#radioPlayer'+station),el=q('#radioLink'+station);RADIO_STATIONS.forEach(s=>{if(s!==station){let oa=q('#radioPlayer'+s),oe=q('#radioLink'+s);if(!oa.paused){oa.pause();oe.classList.remove('playing')}}});if(a.paused){a.play();el.classList.add('playing');startNowPlaying(station)}else{a.pause();el.classList.remove('playing');stopNowPlaying()}}
function startNowPlaying(station){if(radioNowPlayingTimer)clearInterval(radioNowPlayingTimer);let dot=q('#radioStatusDot'),txt=q('#radioStatusText');if(dot)dot.classList.remove('off');if(txt)txt.textContent='On Air';let update=async()=>{try{let r=await api('/api/radio-nowplaying?station='+encodeURIComponent(station));let b=q('#footerBrand');if(b)b.textContent=r.title?('▶ '+RADIO_NAMES[station]+': '+r.title):('▶ '+RADIO_NAMES[station])}catch(e){}};update();radioNowPlayingTimer=setInterval(update,20000)}
function stopNowPlaying(){if(radioNowPlayingTimer){clearInterval(radioNowPlayingTimer);radioNowPlayingTimer=null}let b=q('#footerBrand');if(b)b.textContent='© 2026 SERVICE POINT BÜRO';let dot=q('#radioStatusDot'),txt=q('#radioStatusText');if(dot)dot.classList.add('off');if(txt)txt.textContent='Off Air'}function openPraege(doc){window.open('/praege-pdf?doc='+encodeURIComponent(doc),'_blank','noopener,noreferrer')}function openManualPdf(doc){window.open('/manual-pdf?doc='+encodeURIComponent(doc),'_blank','noopener,noreferrer')}async function showPersonal(){show('personal');await loadNotes()}async function loadNotes(){let ns=await api('/api/personal-notes');q('#personalNoteList').innerHTML=ns.length?ns.map(n=>`<div class="noteItem ${n.done?'done':''}" onclick='editNote(${JSON.stringify(n)})'><b>${esc(n.title)}</b><div class="muted">${esc((n.body||'').slice(0,80))}</div></div>`).join(''):'<div class="muted">Noch keine persönlichen Notizen.</div>'}function newNote(){currentNoteId=0;q('#noteTitle').value='';q('#noteBody').value='';q('#noteDone').checked=false;q('#noteTitle').focus()}function editNote(n){currentNoteId=n.id;q('#noteTitle').value=n.title||'';q('#noteBody').value=n.body||'';q('#noteDone').checked=!!n.done}async function saveNote(){await api('/api/personal-notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:currentNoteId,title:q('#noteTitle').value,body:q('#noteBody').value,done:q('#noteDone').checked})});newNote();loadNotes()}async function deleteNote(){if(!currentNoteId)return;await api('/api/personal-note-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:currentNoteId})});newNote();loadNotes()}let customersCache=[];
async function showCustomers(){show('customers');await loadCustomers()}
async function loadCustomers(){customersCache=await api('/api/customers');renderCustomers()}
let customerTypeFilter='alle';
function renderCustomers(){let f=(q('#customerSearch')?.value||'').toLowerCase();q('#customerTypeTabs').innerHTML=[['alle','Alle'],['Privat','Privatkunden'],['Firma','Firmenkunden']].map(([v,label])=>`<button class="btn ${customerTypeFilter===v?'primary':''}" onclick="customerTypeFilter='${v}';renderCustomers()">${label}</button>`).join('');let list=customersCache.filter(c=>(customerTypeFilter==='alle'||c.customer_type===customerTypeFilter)&&(!f||[c.customer,c.first_name,c.mobile,c.city].some(x=>(x||'').toLowerCase().includes(f))));list.sort((a,b)=>(a.customer||'').localeCompare(b.customer||'','de',{sensitivity:'base'})||(a.first_name||'').localeCompare(b.first_name||'','de',{sensitivity:'base'}));q('#customerTable').innerHTML=list.length?`<table><thead><tr><th>Vorname</th><th>Nachname / Firma</th><th>Typ</th><th>Mobil</th><th>Ort</th><th>Aufträge</th><th>Letzter Auftrag</th><th></th></tr></thead><tbody>${list.map(c=>{let idx=customersCache.indexOf(c);return `<tr data-idx="${idx}"><td><input class="dashCell" data-field="first_name" value="${esc(c.first_name||'')}" onchange="customerCellSave(this)"></td><td><input class="dashCell" data-field="customer" value="${esc(c.customer||'')}" onchange="customerCellSave(this)"></td><td><select class="dashCell" data-field="customer_type" onchange="customerCellSave(this)"><option value="Privat" ${c.customer_type!=='Firma'?'selected':''}>Privat</option><option value="Firma" ${c.customer_type==='Firma'?'selected':''}>Firma</option></select></td><td><input class="dashCell" data-field="mobile" value="${esc(c.mobile||'')}" onchange="customerCellSave(this)"></td><td><input class="dashCell" data-field="city" value="${esc(c.city||'')}" onchange="customerCellSave(this)"></td><td>${c.job_count}</td><td>${c.last_date?fmt(c.last_date):''}</td><td><button type="button" class="dashOpenBtn" onclick='openCustomer(${JSON.stringify(c)})' title="Details & Notiz öffnen">↗</button> <button type="button" class="dashOpenBtn" style="color:var(--danger);border-color:var(--danger)" onclick="event.stopPropagation();deleteCustomer(${idx})" title="Kunde löschen">🗑</button></td></tr>`}).join('')}</tbody></table>`:'<p class="muted">Keine Kunden gefunden.</p>'}
async function deleteCustomer(idx){let c=customersCache[idx];if(!c)return;let name=((c.first_name||'')+' '+(c.customer||'')).trim();if(!c.id){alert(name+' wurde nur automatisch aus Aufträgen übernommen und hat keinen eigenen Kundendatensatz zum Löschen. Die zugehörigen Aufträge können unter "Alle Aufträge" gelöscht werden.');return}if(!confirm('Kunde '+name+' löschen? (Kann 7 Tage lang über Einstellungen → Papierkorb wiederhergestellt werden.)'))return;await api('/api/customer-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:c.id})});await loadCustomers()}
async function customerCellSave(el){let tr=el.closest('tr'),idx=+tr.dataset.idx,field=el.dataset.field,value=el.value,c=customersCache[idx];if(!c)return;let d={...c,[field]:value};if(field==='first_name'||field==='customer'){d.old_customer=c.customer;d.old_first_name=c.first_name}await api('/api/customer-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});await loadCustomers()}
function newCustomer(){let f=q('#cf');f.reset();f.elements.id.value='';f.elements.old_customer.value='';f.elements.old_first_name.value='';f.elements.customer_type.value='Privat';q('#customerEditTitle').textContent='Neuer Kunde';q('#customerJobs').innerHTML='<p class="muted">Noch keine Aufträge.</p>';q('#customerDocs').innerHTML='<p class="muted">Noch keine gescannten Unterlagen hinterlegt.</p>';show('customerEdit')}
function openCustomer(c){let f=q('#cf');f.reset();for(let k of ['id','customer','first_name','mobile','address','postal','city','notes','customer_type'])if(f.elements[k])f.elements[k].value=c[k]||'';f.elements.old_customer.value=c.customer||'';f.elements.old_first_name.value=c.first_name||'';if(!f.elements.customer_type.value)f.elements.customer_type.value='Privat';q('#customerEditTitle').textContent=(c.first_name+' '+c.customer).trim()||'Kunde';show('customerEdit');loadCustomerJobs(c.customer,c.first_name);loadCustomerDocuments(c.customer,c.first_name)}
async function loadCustomerDocuments(name,firstName){let docs=await api('/api/customer-documents?customer='+encodeURIComponent(name||'')+'&first_name='+encodeURIComponent(firstName||''));q('#customerDocs').innerHTML=docs.length?`<div class="portalGrid" style="margin-top:0">${docs.map(d=>`<a class="portalGroup" style="text-decoration:none;color:inherit" href="/customer-document?customer=${encodeURIComponent(name||'')}&first_name=${encodeURIComponent(firstName||'')}&file=${encodeURIComponent(d.file)}" target="_blank"><img src="/customer-document?customer=${encodeURIComponent(name||'')}&first_name=${encodeURIComponent(firstName||'')}&file=${encodeURIComponent(d.file)}" style="width:100%;border-radius:8px;object-fit:cover;max-height:140px"><b style="font-size:12.5px">${esc(d.label)}</b></a>`).join('')}</div>`:'<p class="muted">Noch keine gescannten Unterlagen hinterlegt.</p>'}
function customerJobFields(j){return [['Fahrzeugart',j.vehicle_type],['Kennzeichen',j.plate||j.desired_plate],['Schildergröße',j.sign_size],['Schilder',j.signs],['KZ-Übernahme',j.plate_transfer],['Unterlagen',j.docs],['Fehlt / Rückfrage',j.missing]]}
async function loadCustomerJobs(name,firstName){let jobs=await api('/api/customer-jobs?name='+encodeURIComponent(name||'')+'&first_name='+encodeURIComponent(firstName||''));q('#customerJobs').innerHTML=jobs.length?jobs.map(j=>`<div class="noteItem" style="cursor:pointer" onclick="editJob(${j.id})"><b>${esc(j.process||'Auftrag')}</b><span class="muted"> · ${j.stva_date?fmt(j.stva_date):'ohne StVA-Termin'} · ${esc(j.status||'—')}</span><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:6px 10px;margin-top:8px">${customerJobFields(j).map(([label,val])=>`<div><span class="muted" style="font-size:11px;text-transform:uppercase;letter-spacing:.03em">${label}</span><br>${esc(val||'—')}</div>`).join('')}</div></div>`).join(''):'<p class="muted">Noch keine Aufträge.</p>'}
function levenshtein(a,b){a=(a||'').toLowerCase();b=(b||'').toLowerCase();let m=a.length,n=b.length,dp=Array.from({length:m+1},()=>Array(n+1).fill(0));for(let i=0;i<=m;i++)dp[i][0]=i;for(let j=0;j<=n;j++)dp[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)dp[i][j]=a[i-1]===b[j-1]?dp[i-1][j-1]:1+Math.min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1]);return dp[m][n]}
function findSimilarCustomer(name,firstName,excludeId){name=(name||'').trim();if(name.length<3)return null;let fn=(firstName||'').trim().toLowerCase();for(let c of customersCache){if(!c.customer||(excludeId&&c.id==excludeId))continue;let sameName=name.toLowerCase()===c.customer.toLowerCase();if(sameName&&fn===(c.first_name||'').trim().toLowerCase())continue;if(sameName||levenshtein(name,c.customer)<=2)return c}return null}
async function saveCustomer(){let d=Object.fromEntries(new FormData(q('#cf')).entries());if(!d.id){let similar=findSimilarCustomer(d.customer,d.first_name);if(similar&&!confirm('Ähnlicher Kunde bereits vorhanden: '+((similar.first_name||'')+' '+(similar.customer||'')).trim()+(similar.city?' ('+similar.city+')':'')+'.\n\nTrotzdem als neuen Kunden anlegen?'))return}await api('/api/customer-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});await loadCustomers();show('customers')}
function openSettings(){show('settings');syncAppearanceControls();calibInit();loadBackups();loadDocBackupStatus();showCurrentVersion();loadOpsSettingsUI();loadTrash();showSettingsCategory('darstellung')}
async function loadTrash(){
  let jobsT=(await api('/api/deleted-jobs')).slice(0,5);
  q('#trashJobsList').innerHTML=jobsT.length?jobsT.map(j=>`<div class="backupRow"><span class="backupMeta">${esc(((j.first_name||'')+' '+(j.customer||'')).trim()||'(ohne Namen)')} · gelöscht am ${fmt(j.deleted_at.slice(0,10))}</span><button type="button" class="btn" onclick="restoreJobFromTrash(${j.id})">Wiederherstellen</button></div>`).join(''):'<p class="muted">Papierkorb ist leer.</p>';
  let custT=(await api('/api/deleted-customers')).slice(0,5);
  q('#trashCustomersList').innerHTML=custT.length?custT.map(c=>`<div class="backupRow"><span class="backupMeta">${esc(((c.first_name||'')+' '+(c.customer||'')).trim()||'(ohne Namen)')} · gelöscht am ${fmt(c.deleted_at.slice(0,10))}</span><button type="button" class="btn" onclick="restoreCustomerFromTrash(${c.id})">Wiederherstellen</button></div>`).join(''):'<p class="muted">Papierkorb ist leer.</p>';
}
async function restoreJobFromTrash(id){await api('/api/job-restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await loadTrash();await load();alert('Auftrag wiederhergestellt.')}
async function restoreCustomerFromTrash(id){await api('/api/customer-restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await loadTrash();alert('Kunde wiederhergestellt.')}
const DEFAULT_PICKUP_MESSAGE_CLIENT="Guten Tag,\n\nIhre Unterlagen liegen bei uns Fertig und Abholbereit.\n\nDie Gesamtkosten belaufen sich auf {price} €.\n\nUnsere Öffnungszeiten sind:\n\nMontag und Mittwochs von 07:30 bis 16:30\nDienstags und Donnerstags von 07:30 bis 15:30\nFreitags von 07:30 bis 13:00\n\nMit freundlichen Grüßen \nZulassungsservice Grevenbroich";
async function loadOpsSettingsUI(){appSettings=await api('/api/app-settings');q('#opsPickupMessage').value=appSettings.pickup_message;q('#opsRegularSlots').value=appSettings.regular_slots;q('#opsBufferSlots').value=appSettings.buffer_slots;renderClosedDates();renderRadioToggles();q('#billbeeApiKey').value=appSettings.billbee_api_key||'';q('#billbeeUsername').value=appSettings.billbee_username||'';q('#billbeeApiPassword').value=appSettings.billbee_api_password||''}
async function saveBillbeeSettings(){appSettings=await api('/api/app-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({billbee_api_key:q('#billbeeApiKey').value,billbee_username:q('#billbeeUsername').value,billbee_api_password:q('#billbeeApiPassword').value})});alert('Billbee-Zugangsdaten gespeichert.')}
function recalcFees(){let f=q('#f');if(!f.elements.customer_type)return;let isFirma=f.elements.customer_type.value==='Firma',isAusserbetrieb=f.elements.process.value==='Außerbetriebsetzung',service=isAusserbetrieb?(isFirma?10:20):(isFirma?25:50),signCount=parseInt(f.elements.sign_count.value)||0,signPrice=isFirma?9:15,signs=signCount*signPrice;f.elements.fee_service.value=service.toFixed(2).replace('.',',');f.elements.fee_signs.value=signs.toFixed(2).replace('.',',');recalcFinalPrice()}
function recalcFinalPrice(){let f=q('#f'),n=v=>parseFloat((v||'0').replace(',','.'))||0,sum=n(f.elements.fee_service.value)+n(f.elements.fee_signs.value)+n(f.elements.fee_stva.value);if(sum>0)f.elements.final_price.value=sum.toFixed(2).replace('.',',')}
async function createBillbeeInvoice(id){if(!id){alert('Bitte den Auftrag zuerst speichern.');return}let job=jobs.find(x=>x.id===id)||{},priceVal=(job.final_price||'').toString().trim();if(!priceVal||parseFloat(priceVal.replace(',','.'))===0){if(!confirm('Es ist kein Endpreis eingetragen (0 €). Trotzdem eine Rechnung über 0 € erstellen? Empfehlung: Abbrechen und zuerst den Endpreis eintragen + speichern.'))return}if(!confirm('Rechnung für diesen Auftrag jetzt in Billbee erstellen?'))return;try{let r=await api('/api/billbee-invoice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await load();alert('Rechnung erstellt (Billbee-Bestellung #'+r.billbee_order_id+').')}catch(e){alert('Billbee-Fehler: '+e.message)}}
function resetOpsMessage(){q('#opsPickupMessage').value=DEFAULT_PICKUP_MESSAGE_CLIENT}
async function saveOpsSettings(){let patch={pickup_message:q('#opsPickupMessage').value,regular_slots:+q('#opsRegularSlots').value||8,buffer_slots:+q('#opsBufferSlots').value||0};appSettings=await api('/api/app-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(patch)});q('#opsRegularSlots').value=appSettings.regular_slots;q('#opsBufferSlots').value=appSettings.buffer_slots;alert('Gespeichert.');await load()}
function showSettingsCategory(name){document.querySelectorAll('.settingsCategory').forEach(el=>el.classList.toggle('hidden',el.id!=='settingsCat-'+name));document.querySelectorAll('.settingsTab').forEach(b=>b.classList.toggle('active',b.dataset.cat===name))}
async function showCurrentVersion(){try{let r=await api('/api/update-check');q('#updCurrentVersion').textContent=r.current}catch(e){}}
async function checkUpdate(){let s=q('#updStatus');s.textContent='Suche nach Updates …';q('#updApplyBtn').classList.add('hidden');try{let r=await api('/api/update-check');q('#updCurrentVersion').textContent=r.current;if(r.available){s.textContent='Update gefunden: Version '+r.version+' (aktuell installiert: '+r.current+').';q('#updApplyBtn').classList.remove('hidden');q('#updApplyBtn').dataset.url=r.url}else{s.textContent='Kein Update gefunden. Aktuelle Version ist installiert.'}}catch(e){s.textContent='Fehler bei der Suche: '+e.message}}
async function applyUpdate(){if(!confirm('Update jetzt installieren? Das Programm schließt sich kurz und startet danach neu.'))return;let s=q('#updStatus');s.textContent='Update wird heruntergeladen und installiert, Programm startet gleich neu …';try{await api('/api/update-apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:q('#updApplyBtn').dataset.url})})}catch(e){s.textContent='Fehler: '+e.message}}
async function backupNow(){try{let r=await api('/api/backup-now',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});alert('Sicherung erstellt: '+r.file);await loadBackups();await loadDocBackupStatus()}catch(e){alert(e.message)}}
async function loadDocBackupStatus(){try{let r=await api('/api/document-backup-status');let el=q('#docBackupStatus');if(!el)return;if(r.latest)el.textContent='Dokumente (Scans): zuletzt gesichert am '+fmt(r.latest.mtime.slice(0,10))+' '+r.latest.mtime.slice(11,16)+' Uhr · '+(r.latest.size/1024/1024).toFixed(1)+' MB';else el.textContent='Dokumente (Scans): noch keine Sicherung vorhanden (folgt automatisch mit der nächsten täglichen Sicherung).'}catch(e){}}
async function loadBackups(){try{let list=(await api('/api/backups')).slice(0,3);q('#backupList').innerHTML=list.length?list.map(b=>`<div class="backupRow" title="${esc(b.name)}"><span class="backupMeta">${b.name.includes('manuell')?'Manuell':'Automatisch'} · ${fmt(b.mtime.slice(0,10))} ${b.mtime.slice(11,16)} Uhr · ${(b.size/1024).toFixed(0)} KB</span><button type="button" class="btn" onclick="restoreBackup('${b.name}')">Wiederherstellen</button></div>`).join(''):'<p class="muted">Noch keine Sicherungen vorhanden.</p>'}catch(e){}}
async function restoreBackup(name){if(!confirm('Sicherung "'+name+'" wiederherstellen?\n\nDer aktuelle Stand wird vorher automatisch gesichert, aber alle Änderungen seit dieser Sicherung gehen sonst verloren.\n\nFortfahren?'))return;try{await api('/api/backup-restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});alert('Sicherung wiederhergestellt. Die Seite wird neu geladen.');location.reload()}catch(e){alert(e.message)}}
let calibDrag=null,calibRect=null;
async function calibInit(){try{let r=await api('/api/calibration');q('#calibStatus').textContent=r.configured?'Aktuell: individueller Kalibrierungsbereich gespeichert.':'Aktuell: Standardbereich (keine Kalibrierung gespeichert).'}catch(e){}}
async function calibScan(){q('#calibStatus').textContent='Scanner arbeitet – bitte Ausweis-Vorderseite auflegen …';try{await api('/api/scanner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'id',side:'front',doc_type:'personalausweis'})});let img=q('#calibImage');img.src='/calibration-preview?side=front&t='+Date.now();q('#calibImageWrap').classList.remove('hidden');q('#calibSaveBtn').classList.remove('hidden');q('#calibStatus').textContent='Testscan erstellt. Ziehe mit der Maus ein Rechteck über die Ausweiskarte.';setupCalibDrag();img.onload=calibShowSaved}catch(e){q('#calibStatus').textContent='Fehler: '+e.message}}
function setupCalibDrag(){let wrap=q('#calibImageWrap'),box=q('#calibBox'),img=q('#calibImage');wrap.onmousedown=e=>{let r=img.getBoundingClientRect();calibDrag={x0:e.clientX-r.left,y0:e.clientY-r.top,r};box.style.display='block';box.style.left=calibDrag.x0+'px';box.style.top=calibDrag.y0+'px';box.style.width='0px';box.style.height='0px';e.preventDefault()};wrap.onmousemove=e=>{if(!calibDrag)return;let r=calibDrag.r,x=Math.max(0,Math.min(e.clientX-r.left,r.width)),y=Math.max(0,Math.min(e.clientY-r.top,r.height)),x1=Math.min(x,calibDrag.x0),y1=Math.min(y,calibDrag.y0),w=Math.abs(x-calibDrag.x0),h=Math.abs(y-calibDrag.y0);box.style.left=x1+'px';box.style.top=y1+'px';box.style.width=w+'px';box.style.height=h+'px';calibRect={x1:x1/r.width,y1:y1/r.height,x2:(x1+w)/r.width,y2:(y1+h)/r.height}};wrap.onmouseup=()=>{calibDrag=null};wrap.onmouseleave=()=>{calibDrag=null}}
async function calibShowSaved(){try{let r=await api('/api/calibration');if(r.configured){let img=q('#calibImage'),rect=img.getBoundingClientRect(),box=q('#calibBox');box.style.display='block';box.style.left=(r.id_box[0]*rect.width)+'px';box.style.top=(r.id_box[1]*rect.height)+'px';box.style.width=((r.id_box[2]-r.id_box[0])*rect.width)+'px';box.style.height=((r.id_box[3]-r.id_box[1])*rect.height)+'px';calibRect={x1:r.id_box[0],y1:r.id_box[1],x2:r.id_box[2],y2:r.id_box[3]}}}catch(e){}}
