async function calibReset(){await api('/api/calibration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({box:null})});q('#calibStatus').textContent='Zurückgesetzt auf Standardbereich.';let box=q('#calibBox');if(box)box.style.display='none';calibRect=null}function applyAppearance(a){a=a||{};let r=document.documentElement.style,accent=a.accent||'#1D6FD1',accent2=a.accent2||'#0E4E9C',bg=a.bg||'#F3F5F8',panel=a.panel||'#FFFFFF';r.setProperty('--accent',accent);r.setProperty('--accent-strong',accent2);r.setProperty('--bg',bg);r.setProperty('--panel',panel);let hero=document.querySelector('.workHeader');if(hero){if(a.heroData)hero.style.setProperty('background-image',`linear-gradient(90deg,rgba(255,255,255,.92) 0%,rgba(255,255,255,.7) 45%,rgba(255,255,255,.25) 100%),url("${a.heroData}")`,'important');else hero.style.removeProperty('background-image')}}
