function openFormCategory(key){let c=FORM_CATEGORIES[key];if(!c)return;q('#formCatTitle').textContent=c.title;q('#formCatSub').textContent=c.sub;q('#formCatGrid').innerHTML=c.items.map((x,i)=>`<div class="portalGroup formPdfItem"><div class="portalHead"><span class="portalIcon">PDF</span><div><h3>${esc(x[1])}</h3><span>${esc(x[2]||'Manueller Zugriff')}</span></div></div><button class="portalBtn ${i===0&&key==='kauf'?'primaryPortal':''}" onclick="openManualPdf('${x[0]}')"><b>PDF öffnen</b><small>Öffnen · ausfüllen · drucken</small></button></div>`).join('');show('manualpdfcat')}function filterManualPdfs(){let term=(q('#manualPdfSearch')?.value||'').trim().toLowerCase();document.querySelectorAll('.manualPdfCard').forEach(c=>{let hay=(c.innerText+' '+(c.dataset.tags||'')).toLowerCase();c.style.display=!term||hay.includes(term)?'flex':'none'})}function filterPraege(){let term=(q('#praegeSearch')?.value||'').trim().toLowerCase();document.querySelectorAll('.praegeCard').forEach(c=>{let hay=(c.innerText+' '+(c.dataset.tags||'')).toLowerCase();c.style.display=!term||hay.includes(term)?'flex':'none'})}function fmt(d){if(!d)return'';let p=d.split('-');return p.length===3?p[2]+'.'+p[1]+'.'+p[0]:d}function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function isoToday(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function nextWorkdayClient(){let d=new Date();do{d.setDate(d.getDate()+1)}while(d.getDay()===0||d.getDay()===6||nrwHolidayName(d));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
