function slotWeight(j){let p=String(j?.process||'').toLowerCase();if(p.includes('online-abmeldung')||p.includes('kauf / verkauf')||p.includes('kauf/verkauf'))return 0;return String(j?.plate_transfer||'').toLowerCase()==='ja'?2:1}function expandSlots(arr){let out=[];arr.forEach(j=>{let w=slotWeight(j);if(w===0)return;if(w===2){out.push({...j,_slotLabel:'A · Altfahrzeug abmelden',process:'Außerbetriebsetzung · Altfahrzeug'});out.push({...j,_slotLabel:'B · Neues Fahrzeug zulassen',process:(j.process||'Zulassung')+' · Neufahrzeug'})}else out.push(j)});return out}function jobRow(j,n,buffer=false){return `<tr class="${buffer?'buffer':''}" onclick="editJob(${j.id})" style="cursor:pointer"><td>${n}${buffer?' · Puffer':''}${j._slotLabel?' · '+j._slotLabel:''}</td><td>${fmt(j.stva_date)}</td><td>${esc(((j.first_name||'')+' '+(j.customer||'')).trim())}</td><td>${esc(j.mobile)}</td><td>${esc(j.vehicle_type)}</td><td>${esc(j.plate||j.desired_plate)}</td><td>${esc(j.process)}</td><td>${esc(j.sign_size)}</td><td>${esc(j.signs)}</td><td>${esc(j.plate_transfer)}</td><td>${esc(j.docs)}</td><td>${esc(j.missing)}</td><td>${esc(j.status)}</td><td><button class="btn" onclick="event.stopPropagation();quickMove(${j.id})">Verschieben</button> <button class="btn danger" onclick="event.stopPropagation();deleteJob(${j.id})">Löschen</button></td></tr>`}
