function printToday(){window.print()}
function openTodayCalendar(){allYear=new Date().getFullYear();allMonth=new Date().getMonth();allDay=-1;show('all')}
function easterSunday(y){let a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mo=Math.floor((h+l-7*m+114)/31)-1,day=((h+l-7*m+114)%31)+1;return new Date(y,mo,day)}
function isoLocal(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function addDays(d,n){let x=new Date(d);x.setDate(x.getDate()+n);return x}
function nrwHolidayName(date){let y=date.getFullYear(),key=isoLocal(date),e=easterSunday(y),h={};h[y+'-01-01']='Neujahr';h[y+'-05-01']='Tag der Arbeit';h[y+'-10-03']='Tag der Deutschen Einheit';h[y+'-11-01']='Allerheiligen';h[y+'-12-25']='1. Weihnachtstag';h[y+'-12-26']='2. Weihnachtstag';h[isoLocal(addDays(e,-2))]='Karfreitag';h[isoLocal(addDays(e,1))]='Ostermontag';h[isoLocal(addDays(e,39))]='Christi Himmelfahrt';h[isoLocal(addDays(e,50))]='Pfingstmontag';h[isoLocal(addDays(e,60))]='Fronleichnam';return h[key]||(appSettings.closed_dates&&appSettings.closed_dates[key])||''}
function monthDayBlocks(year,month,groups){let last=new Date(year,month+1,0).getDate(),body='';for(let day=1;day<=last;day++){let d=new Date(year,month,day),iso=isoLocal(d),holiday=nrwHolidayName(d),weekend=d.getDay()===0||d.getDay()===6,arr=(groups[iso]||[]).sort((a,b)=>a.id-b.id);if(weekend||holiday){let why=holiday?`<span class="holidayName">${holiday}</span> · Kein StVA-Tag`:'Wochenende · Kein StVA-Tag';body+=`<tr class="closedDay"><td colspan="14">${fmt(iso)} · ${why}</td></tr><tr class="closedSpacer"><td colspan="14"></td></tr>`}else{body+=dayBlock(iso,arr)+`<tr class="daySpacer"><td colspan="14"></td></tr>`}}return body}
function unscheduledRows(arr){if(!arr.length)return'';return `<tr class="dayhead unscheduledHead"><td colspan="14">Ohne StVA-Termin / kein StVA-Platz erforderlich · ${arr.length} Auftrag${arr.length===1?'':'e'}</td></tr>`+arr.map((j,i)=>`<tr onclick="editJob(${j.id})" style="cursor:pointer"><td>—</td><td>—</td><td>${esc(((j.first_name||'')+' '+(j.customer||'')).trim())}</td><td>${esc(j.mobile)}</td><td>${esc(j.vehicle_type)}</td><td>${esc(j.plate||j.desired_plate)}</td><td>${esc(j.process)}</td><td>${esc(j.sign_size)}</td><td>${esc(j.signs)}</td><td>${esc(j.plate_transfer)}</td><td>${esc(j.docs)}</td><td>${esc(j.missing)}</td><td>${esc(j.status)}</td><td><button class="btn" onclick="event.stopPropagation();editJob(${j.id})">Öffnen</button></td></tr>`).join('')}
