function allDateLabel(){if(allMonth===-2)return'▾ Ohne StVA-Termin';if(allMonth>=0&&allDay>=1)return'▾ '+String(allDay).padStart(2,'0')+'.'+String(allMonth+1).padStart(2,'0')+'.'+allYear;if(allMonth>=0)return'▾ '+MONTH_NAMES_FULL[allMonth]+' '+allYear+' · ganzer Monat';return'▾ Alle Aufträge '+allYear}
