function renderAllDayPicker(){let y=allYear,m=allMonth>=0?allMonth:new Date().getMonth(),last=new Date(y,m+1,0).getDate(),btns=[];for(let day=1;day<=last;day++){let wd=new Date(y,m,day).getDay(),closed=wd===0||wd===6||!!nrwHolidayName(new Date(y,m,day)),active=(allMonth===m&&allYear===y&&allDay===day);btns.push(`<button type="button" class="dashDayBtn ${active?'active':''} ${closed?'closedDay2':''}" onclick="allYear=${y};allMonth=${m};allDay=${day};toggleAllDayPicker();renderAll()">${day}</button>`)}q('#allDayPicker').innerHTML=`<div class="dashDayPickerHead"><button type="button" class="btn" onclick="event.stopPropagation();allMonthShift(-1)">‹</button><b>${MONTH_NAMES_FULL[m]} ${y}</b><button type="button" class="btn" onclick="event.stopPropagation();allMonthShift(1)">›</button></div><div class="dashDayGrid">${btns.join('')}</div><div class="actions" style="margin-top:10px;gap:6px;flex-wrap:wrap"><button type="button" class="btn" onclick="allYear=${y};allMonth=${m};allDay=-1;toggleAllDayPicker();renderAll()">Ganzer Monat</button><button type="button" class="btn" onclick="allMonth=-1;allDay=-1;toggleAllDayPicker();renderAll()">Ganzes Jahr</button><button type="button" class="btn" onclick="allMonth=-2;allDay=-1;toggleAllDayPicker();renderAll()">Ohne StVA</button><button type="button" class="btn dashTodayBtn" onclick="let td=new Date();allYear=td.getFullYear();allMonth=td.getMonth();allDay=td.getDate();toggleAllDayPicker();renderAll()">Heute</button></div>`}
