function updatePreplanInfo(){let f=q('#preplanForm'),v=f.elements.stva_date.value;if(!v)return;let d=new Date(v+'T12:00:00'),h=nrwHolidayName(d),weekend=d.getDay()===0||d.getDay()===6,count=jobs.filter(j=>j.stva_date===v).reduce((a,j)=>a+slotWeight(j),0),proc=f.elements.process.value,needed=(proc==='Kennzeichenübernahme'?2:(proc==='Online-Abmeldung'?0:1)),el=q('#preplanInfo');if(needed===0){el.innerHTML='<b>Online-Abmeldung:</b> kein StVA-Platz erforderlich.';return}if(weekend||h)el.innerHTML='<b>Dieser Tag ist kein StVA-Arbeitstag.</b> '+(h||'Wochenende')+'. Beim Speichern wird auf den nächsten möglichen Arbeitstag verschoben.';else el.innerHTML='<b>'+fmt(v)+'</b> · aktuell '+Math.min(count,appSettings.regular_slots)+'/'+appSettings.regular_slots+' reguläre Plätze belegt · '+Math.max(0,appSettings.regular_slots-count)+' regulär frei.'+(needed===2?' <b>Kennzeichenübernahme benötigt 2 reguläre Plätze.</b>':'')}
