let scanBusy=false;
async function launchScan(kind,side=''){if(scanBusy)return;scanBusy=true;window.lastOCR=null;window.scanStatus='Scanner arbeitet - bitte Vorlage liegen lassen ...';renderWizard();try{let r=await api('/api/scanner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,side,doc_type:(kind==='id'?(intake.id_type||'personalausweis'):kind==='taxpayer_id'?(intake.taxpayer_id_type||'personalausweis'):'')})});if(kind==='id'&&side==='front'){intake.id_front=true;window.scanStatus='✓ Vorderseite gespeichert. Jetzt Ausweis wenden und Rückseite scannen.'}else if(kind==='id'&&side==='back'){intake.id_back=true;window.scanStatus='✓ Rückseite gespeichert. Ausweisscan vollständig.'}else if(kind==='bank'){intake.bank_done=true;window.scanStatus='✓ Bankkarte gespeichert.'}else if(kind==='extra'){intake.extra_done=true;window.scanStatus='✓ Zusatzdokument gespeichert.'}else if(kind==='handelsregister'){intake.handelsregister_done=true;window.scanStatus='✓ Handelsregisterauszug gespeichert.'}else if(kind==='gewerbeanmeldung'){intake.gewerbeanmeldung_done=true;window.scanStatus='✓ Gewerbeanmeldung gespeichert.'}else if(kind==='taxpayer_id'&&side==='front'){intake.taxpayer_id_front=true;window.scanStatus=intake.taxpayer_id_type==='reisepass'?'✓ Reisepass des abweichenden Steuerzahlers gespeichert.':'✓ Vorderseite gespeichert. Jetzt Ausweis wenden und Rückseite scannen.'}else if(kind==='taxpayer_id'&&side==='back'){intake.taxpayer_id_back=true;window.scanStatus='✓ Rückseite gespeichert. Ausweisscan des abweichenden Steuerzahlers vollständig.'}}catch(e){window.scanStatus='Scanfehler: '+e.message}finally{scanBusy=false;renderWizard()}}
function scanState(){return window.scanStatus?`<div class="${window.scanStatus.startsWith('Scanfehler')?'warnbox':'okbox'}">${window.scanStatus}</div>`:''}
async function recognize(kind){try{let r=await api('/api/ocr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind})});window.lastOCR=r;if(kind==='bank'){let f=q('#f');if(r.iban)f.elements.iban.value=r.iban;if(r.account_holder)f.elements.account_holder.value=r.account_holder;}renderWizard();}catch(e){alert(e.message)}}
function setOCRValue(k,v){if(window.lastOCR)window.lastOCR[k]=v}
function acceptIdOCR(){let r=window.lastOCR;if(!r)return;let f=q('#f'),map={customer:'customer',first_name:'first_name',address:'address',postal:'postal',city:'city'};for(let [k,n] of Object.entries(map)){if(r[k])f.elements[n].value=r[k]}window.scanStatus='✓ Ausweisdaten kontrolliert und übernommen.';window.lastOCR=null;renderWizard()}
function idOCRReview(){let r=window.lastOCR;if(!r)return '';let fields=[['customer','Nachname'],['first_name','Vorname'],['address','Straße / Hausnummer'],['postal','PLZ'],['city','Ort']];return `<div class="ocrReview"><div class="ocrReviewHead"><div><b>Erkannte Ausweisdaten kontrollieren</b><small>Nur diese fünf Werte werden übernommen. Bitte kurz prüfen und bei Bedarf korrigieren.</small></div><span>${r.duration_ms?Math.round(r.duration_ms/1000)+' s':''}</span></div><div class="ocrReviewGrid">${fields.map(x=>`<label>${x[1]}<input value="${esc(r[x[0]]||'')}" oninput="setOCRValue('${x[0]}',this.value)"></label>`).join('')}</div><div class="ocrReviewActions"><button class="btn primary" onclick="acceptIdOCR()">✓ Daten übernehmen</button></div></div>`}
function navStep(n){intakeStep=Math.max(0,Math.min(activeSteps().length-1,n));renderWizard()}
let calStart=null,calBox=null;
async function openCalibration(){q('#calOverlay').classList.remove('hidden');calBox=null;q('#calRect').classList.add('hidden');loadCalibrationPreview()}
function ocrDiag(){let r=window.lastOCR;if(!r)return '';let previews=(r.preview_files||[]).flat().filter(Boolean);let gallery=previews.length?'<div class="ocrPreviewGrid">'+previews.map((x,i)=>'<div><small>'+(['Ausschnitt','Optimiert','Schwarz/Weiß'][i%3]||'Vorschau')+'</small><img src="/scan-preview?file='+encodeURIComponent(x)+'&t='+Date.now()+'"></div>').join('')+'</div>':'';let raw=(r.raw||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');let rot=(r.rotations||[]).map((x,i)=>((r.scan_files||[])[i]||'Scan')+': '+x+'°').join(' · ');return `<details class="ocrTech"><summary>OCR-Diagnose anzeigen</summary><div class="ocrTechBody"><b>Technische Diagnose</b><br>Texterkennung ${r.ocr_ok?'✓':'✗'} · MRZ ${r.mrz_found?(r.mrz_valid?'✓ geprüft':'⚠ gefunden'):'—'} · Zeit ${r.duration_ms||0} ms${r.scan_mode?' · '+r.scan_mode:''}<br><span class="muted">${rot}</span>${gallery}${(r.mrz_lines||[]).length?'<details><summary>MRZ-Rohzeilen</summary><pre>'+r.mrz_lines.join('\n')+'</pre></details>':''}<details><summary>OCR-Rohtext</summary><pre>${raw}</pre></details></div></details>`}
function requirementBox(){if(!intake.process)return `<div class="requirementHint">Vorgang auswählen – danach zeigt SERVICE POINT sofort die benötigten Unterlagen und Prüfhinweise.</div>`;let p=profile(),req=['Personalausweis / Reisepass',...p.req.map(x=>DOC_LABEL[x]||x)];if(p.evb)req.push('eVB');if(p.bank)req.push('SEPA / Bank- und Steuerzahlerdaten');let cond=p.cond||[];return `<div class="requirementPanel"><div class="reqTitle"><b>Für ${esc(intake.process)} bereithalten</b><span>${req.length} Pflichtpunkte</span></div><div class="reqChips">${req.map(x=>`<span>✓ ${esc(x)}</span>`).join('')}</div>${cond.length?`<div class="reqConditional"><b>NUR WENN:</b> ${cond.map(x=>esc(x)).join(' · ')}</div>`:''}</div>`}
function normalizeIban(v){return String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function formatIban(v){let x=normalizeIban(v);return x.replace(/(.{4})/g,'$1 ').trim()}
function bankField(name,v,el){
 let f=q('#f');
 if(name==='iban'){
   let raw=normalizeIban(v).slice(0,22), formatted=formatIban(raw);
   f.elements[name].value=formatted;
   if(el && el.value!==formatted){let pos=formatted.length;el.value=formatted;try{el.setSelectionRange(pos,pos)}catch(e){}}
 }else f.elements[name].value=v;
 updateBankLive();
}
function taxField(name,v){q('#f').elements[name].value=v;updateBankLive()}
function vehicleField(name,v){q('#f').elements[name].value=v}
function bankComplete(){
 let f=q('#f'),iban=f.elements.iban.value||'',holder=f.elements.account_holder.value||'',sameTax=intake.taxpayer_same_holder!==false;
 let tn=f.elements.taxpayer_name.value||'',ta=f.elements.taxpayer_address.value||'',tp=f.elements.taxpayer_postal.value||'',tc=f.elements.taxpayer_city.value||'';
 return !!iban.trim()&&!!holder.trim()&&(sameTax||!!tn.trim())&&(sameTax||!!ta.trim())&&(sameTax||/^\d{5}$/.test(tp.trim()))&&(sameTax||!!tc.trim());
}
function updateBankLive(){
 intake.bank_done=bankComplete();
 let all=q('#bankCompleteState');if(all){all.className=intake.bank_done?'okbox':'requirementHint';all.innerHTML=intake.bank_done?'<b>✓ Bank- und Steuerdaten vollständig.</b>':'Für „Weiter“ bitte IBAN, Kontoinhaber und – falls abweichend – die vollständige Steuerzahleranschrift erfassen.'}
}
function setTaxpayerSame(v){intake.taxpayer_same_holder=!!v;let f=q('#f');f.elements.taxpayer_same_holder.value=v?'Ja':'Nein';if(v){f.elements.taxpayer_first_name.value=f.elements.first_name.value||'';f.elements.taxpayer_name.value=f.elements.customer.value||'';f.elements.taxpayer_address.value=f.elements.address.value||'';f.elements.taxpayer_postal.value=f.elements.postal.value||'';f.elements.taxpayer_city.value=f.elements.city.value||'';}renderWizard()}
function setAccountSameTaxpayer(v){intake.account_holder_same_taxpayer=!!v;q('#f').elements.account_holder_same_taxpayer.value=v?'Ja':'Nein';if(v){let f=q('#f'),name=intake.taxpayer_same_holder!==false?((f.elements.first_name.value+' '+f.elements.customer.value).trim()):((f.elements.taxpayer_first_name.value+' '+f.elements.taxpayer_name.value).trim());if(name)f.elements.account_holder.value=name;}renderWizard()}
function renderWizard(){chips();let b=q('#wizardbody'),steps=activeSteps(),step=steps[intakeStep];let back=`<button class="btn" onclick="navStep(${intakeStep-1})" ${intakeStep===0?'disabled':''}>Zurück</button>`;let next=`<button class="btn primary" onclick="navStep(${intakeStep+1})" ${step==='Auftragswahl'&&!intake.process?'disabled':''}>Weiter</button>`;
if(step==='Auftragswahl'){let procs=['Neuzulassung','Wiederzulassung','Umschreibung','Außerbetriebsetzung','Änderung Fahrzeugtechnik','Änderung Halterdaten','Ersatzausstellung ZB I','Ausfuhrkennzeichen','Kurzzeitkennzeichen','Kennzeichenverlust'];b.innerHTML=`<h3>1. Auftragswahl</h3><p>Um welche Angelegenheit handelt es sich?</p><div class="processGrid">${procs.map(x=>`<button class="choice ${intake.process===x?'selected':''}" onclick="setChoice('process','${x}')"><b>${x}</b></button>`).join('')}</div>${requirementBox()}<div class="transferBox"><label class="checkline"><input type="checkbox" ${intake.plate_transfer?'checked':''} onchange="check('plate_transfer',this)"> <b>Kennzeichenübernahme vom bisherigen Fahrzeug</b></label><div class="muted">Kennzeichenübernahme reserviert automatisch <b>2 reguläre StVA-Plätze</b>.</div></div><div class="transferBox"><div class="muted" style="margin-bottom:8px"><b>Privat- oder Firmenkunde?</b></div><div class="bigchoice"><button class="choice ${intake.customer_kind!=='firma'?'selected':''}" onclick="setChoice('customer_kind','privat')"><b>Privatkunde</b></button><button class="choice ${intake.customer_kind==='firma'?'selected':''}" onclick="setChoice('customer_kind','firma')"><b>Firmenkunde</b></button></div></div><div class="wizardfoot">${back}${next}</div>`}
else if(step==='Identität')b.innerHTML=`<h3>Identitätsdokument</h3><p>Welches Dokument legt der Kunde vor?</p><div class="bigchoice">${[['personalausweis','Personalausweis'],['reisepass','Reisepass']].map(x=>`<button class="choice ${intake.id_type===x[0]?'selected':''}" onclick="setChoice('id_type','${x[0]}')"><b>${x[1]}</b></button>`).join('')}</div><div class="infobox" style="margin-top:12px"><b>Scanposition:</b> Dokument bündig oben links auf das Flachbett legen. Die Software schneidet nur diesen Kartenbereich aus dem A4-Scan aus.</div><div class="actions"><button class="btn primary scanbtn" onclick="launchScan('id','front')">🪪 ${intake.id_type==='reisepass'?'Reisepass scannen':'1. Vorderseite scannen'}</button>${intake.id_type==='reisepass'?'':`<button class="btn primary scanbtn" onclick="launchScan('id','back')">↩ 2. Rückseite scannen</button>`}</div>${scanState()}<button class="btn ocrAction" style="margin-top:16px" onclick="recognize('id')">🔎 Vorname, Nachname und Anschrift erkennen</button>${idOCRReview()}${ocrDiag()}<h3 style="margin-top:22px">Meldebescheinigung</h3><p>Ist eine Meldebescheinigung oder ein anderer zusätzlicher Nachweis erforderlich?</p><div class="bigchoice"><button class="choice ${intake.extra_needed?'selected':''}" onclick="setChoice('extra_needed',true)"><b>Ja</b></button><button class="choice ${!intake.extra_needed?'selected':''}" onclick="setChoice('extra_needed',false)"><b>Nein</b></button></div>${intake.extra_needed?`<button class="btn primary scanbtn" onclick="launchScan('extra')">📄 Zusatzdokument scannen</button>${scanState()}<label class="checkline"><input type="checkbox" ${intake.extra_done?'checked':''} onchange="check('extra_done',this)"> Zusatzdokument gescannt</label>`:'<div class="okbox">Kein Zusatzdokument ausgewählt.</div>'}<div class="wizardfoot">${back}${next}</div>`;
else if(step==='Firmenunterlagen')b.innerHTML=`<h3>Firmenunterlagen</h3><p>Als Firmenkunde bitte Handelsregisterauszug und Gewerbeanmeldung scannen.</p><button class="btn primary scanbtn" onclick="launchScan('handelsregister')">📄 Handelsregisterauszug scannen</button>${scanState()}<label class="checkline"><input type="checkbox" ${intake.handelsregister_done?'checked':''} onchange="check('handelsregister_done',this)"> Handelsregisterauszug gescannt</label><button class="btn primary scanbtn" style="margin-top:10px" onclick="launchScan('gewerbeanmeldung')">📄 Gewerbeanmeldung scannen</button>${scanState()}<label class="checkline"><input type="checkbox" ${intake.gewerbeanmeldung_done?'checked':''} onchange="check('gewerbeanmeldung_done',this)"> Gewerbeanmeldung gescannt</label><div class="wizardfoot">${back}${next}</div>`;
else if(step==='Bank'){
let f=q('#f'),iban=f.elements.iban.value||'',holder=f.elements.account_holder.value||'';
let sameTax=intake.taxpayer_same_holder!==false, sameAcct=intake.account_holder_same_taxpayer!==false;
let tf=f.elements.taxpayer_first_name.value||'',tn=f.elements.taxpayer_name.value||'',ta=f.elements.taxpayer_address.value||'',tp=f.elements.taxpayer_postal.value||'',tc=f.elements.taxpayer_city.value||'';
intake.bank_done=!!iban.trim()&&!!holder.trim()&&(sameTax||!!tn.trim())&&(sameTax||!!ta.trim())&&(sameTax||/^\d{5}$/.test(tp.trim()))&&(sameTax||!!tc.trim());
b.innerHTML=`<h3>Bank & Steuerzahler</h3><p>Bankverbindung manuell erfassen.</p>
<div class="grid" style="margin-top:12px"><label>IBAN<input id="wizIban" value="${esc(formatIban(iban))}" oninput="bankField('iban',this.value,this)" placeholder="DE00 0000 0000 0000 0000 00" autocomplete="off" spellcheck="false"></label><label>Kontoinhaber<input value="${esc(holder)}" oninput="bankField('account_holder',this.value,this)" placeholder="Vorname Nachname / Firma"></label></div>
<div class="taxModeTitle">Wer ist der Steuerzahler?</div><div class="taxModeGrid"><button class="taxMode ${sameTax?'selected':''}" onclick="setTaxpayerSame(true)"><span class="taxIcon">✓</span><span><b>Fahrzeughalter</b><small>Steuerzahler und Fahrzeughalter sind identisch</small></span></button><button class="taxMode ${!sameTax?'selected':''}" onclick="setTaxpayerSame(false)"><span class="taxIcon">↔</span><span><b>Abweichender Steuerzahler</b><small>Andere Person oder Firma mit eigener Anschrift</small></span></button></div>
${sameTax?'':`<div class="subPanel"><h4>Angaben zum abweichenden Steuerzahler</h4><div class="grid"><label>Vorname<input value="${esc(tf)}" oninput="taxField('taxpayer_first_name',this.value)"></label><label>Nachname / Firma<input value="${esc(tn)}" oninput="taxField('taxpayer_name',this.value)"></label><label class="wide">Straße / Hausnummer<input value="${esc(ta)}" oninput="taxField('taxpayer_address',this.value)"></label><label>PLZ<input value="${esc(tp)}" maxlength="5" inputmode="numeric" oninput="this.value=this.value.replace(/\D/g,'').slice(0,5);taxField('taxpayer_postal',this.value)"></label><label>Ort<input value="${esc(tc)}" oninput="taxField('taxpayer_city',this.value)"></label></div><div class="bigchoice" style="margin-top:14px">${[['personalausweis','Personalausweis'],['reisepass','Reisepass']].map(x=>`<button class="choice ${(intake.taxpayer_id_type||'personalausweis')===x[0]?'selected':''}" onclick="setChoice('taxpayer_id_type','${x[0]}')"><b>${x[1]}</b></button>`).join('')}</div><div class="actions"><button class="btn primary scanbtn" onclick="launchScan('taxpayer_id','front')">🪪 ${intake.taxpayer_id_type==='reisepass'?'Reisepass scannen':'1. Vorderseite scannen'}</button>${intake.taxpayer_id_type==='reisepass'?'':`<button class="btn primary scanbtn" onclick="launchScan('taxpayer_id','back')">↩ 2. Rückseite scannen</button>`}</div>${scanState()}${(intake.taxpayer_id_front&&(intake.taxpayer_id_type==='reisepass'||intake.taxpayer_id_back))?'<div class="okbox">✓ Ausweisdokument des abweichenden Steuerzahlers gescannt.</div>':''}</div>`}

<div id="bankCompleteState" class="${intake.bank_done?'okbox':'requirementHint'}">${intake.bank_done?'<b>✓ Bank- und Steuerdaten vollständig.</b>':'IBAN, Kontoinhaber und – falls abweichend – die vollständige Steuerzahleranschrift können auch später ergänzt werden.'}</div>
<div class="wizardfoot">${back}<button id="bankNext" class="btn primary" onclick="navStep(${intakeStep+1})">Weiter</button></div>`;}
else if(step==='Fahrzeugdaten'){let f=q('#f');b.innerHTML=`<h3>Fahrzeugdaten</h3><p>Angaben für Vollmacht und Zulassung.</p><div class="grid"><label>Hersteller / Typ<input value="${esc(f.elements.manufacturer.value)}" oninput="vehicleField('manufacturer',this.value)"></label><label>FIN (Fahrzeug-Ident.-Nr.)<input value="${esc(f.elements.fin.value)}" oninput="vehicleField('fin',this.value)"></label><label>KFZ-Brief / ZB II-Nr.<input value="${esc(f.elements.zb2.value)}" oninput="vehicleField('zb2',this.value)"></label><label>Zukünftiges amtl. Kennzeichen<input value="${esc(f.elements.plate.value)}" oninput="vehicleField('plate',this.value)"></label><label>ggf. Wunschkennzeichen<input value="${esc(f.elements.desired_plate.value)}" oninput="vehicleField('desired_plate',this.value)"></label><label>Referenz-Nr. eVB<input value="${esc(f.elements.evb.value)}" oninput="vehicleField('evb',this.value)"></label></div><div class="wizardfoot">${back}${next}</div>`}
else if(step==='Fahrzeugunterlagen'){let p=profile(),keys=[...new Set([...p.req])];if(p.evb)keys.push('evb_doc');let needOldPlates=intake.plate_transfer&&['Neuzulassung','Wiederzulassung','Umschreibung'].includes(intake.process);b.innerHTML=`<h3>Fahrzeugunterlagen</h3><p><b>Pflicht laut Prüfprofil zuerst.</b> Markiere, was tatsächlich vorliegt.</p>${keys.map(k=>{let label=k==='evb_doc'?'eVB vorhanden':DOC_LABEL[k];let req=p.req.includes(k)||(k==='evb_doc'&&p.evb);return `<label class="checkline"><input type="checkbox" ${intake[k]?'checked':''} onchange="check('${k}',this)"> ${req?'<b>PFLICHT · </b>':''}${label}</label>`}).join('')}${intake.plate_transfer?`<div class="warnbox"><b>Kennzeichenübernahme:</b> Unterlagen von Alt- und Neufahrzeug getrennt prüfen. 2 reguläre Tagesplätze.${needOldPlates?`<label class="checkline"><input type="checkbox" ${intake.old_plates_received?'checked':''} onchange="check('old_plates_received',this)"> Kennzeichenschilder des alten Fahrzeugs erhalten</label><label class="checkline"><input type="checkbox" ${intake.old_vehicle_doc_received?'checked':''} onchange="check('old_vehicle_doc_received',this)"> Fahrzeugschein (ZB I) des alten Fahrzeugs erhalten</label>`:''}</div>`:''}<h3 style="margin-top:22px">Weitere Formulare</h3>${intake.customer_kind==='firma'?`<label class="checkline"><input type="checkbox" ${intake.need_gbr?'checked':''} onchange="check('need_gbr',this)"> Haftungserklärung GbR benötigt</label>`:''}${intake.process==='Kurzzeitkennzeichen'?`<label class="checkline"><input type="checkbox" ${intake.need_kurzzeit?'checked':''} onchange="check('need_kurzzeit',this)"> Kurzzeitkennzeichen – Empfangsbevollmächtigter benötigt</label>`:''}<label class="checkline"><input type="checkbox" ${intake.need_ausland_kz?'checked':''} onchange="check('need_ausland_kz',this)"> Verbleib ausländischer Kennzeichen benötigt</label><label class="checkline"><input type="checkbox" ${intake.need_erhalt?'checked':''} onchange="checkPrint('need_erhalt',this,'erhalt')"> Erhalt der Fahrzeugpapiere erforderlich</label><div class="wizardfoot">${back}${next}</div>`}
else {let p=profile(),okId=intake.id_front&&(intake.id_type==='reisepass'||intake.id_back),okExtra=!intake.extra_needed||intake.extra_done,needOldPlates=intake.plate_transfer&&['Neuzulassung','Wiederzulassung','Umschreibung'].includes(intake.process),reqOk=p.req.every(k=>!!intake[k])&&(!p.evb||intake.evb_doc)&&(!p.bank||intake.bank_done)&&(!needOldPlates||(intake.old_plates_received&&intake.old_vehicle_doc_received))&&(intake.customer_kind!=='firma'||(intake.handelsregister_done&&intake.gewerbeanmeldung_done));let items=[['Auftrag: '+intake.process,true],[intake.id_type==='reisepass'?'Reisepass':'Ausweis vollständig',okId],['Zusatzdokument',okExtra],...(p.bank?[['Bank / SEPA',intake.bank_done]]:[]),...p.req.map(k=>[DOC_LABEL[k],!!intake[k]]),...(p.evb?[['eVB vorhanden',intake.evb_doc]]:[]),...(intake.customer_kind==='firma'?[['Handelsregisterauszug',intake.handelsregister_done],['Gewerbeanmeldung',intake.gewerbeanmeldung_done]]:[])];let ready=okId&&okExtra&&reqOk;b.innerHTML=`<h3>Abschlusskontrolle</h3><div class="summarygrid">${items.map(x=>`<div class="summaryitem ${x[1]?'ok':'missing'}">${x[1]?'✓':'○'} ${x[0]}</div>`).join('')}</div>${ready?'<div class="okbox"><b>Prüfprofil vollständig.</b> Auftrag kann weiter erfasst werden.</div>':'<div class="warnbox"><b>Noch nicht STVA-bereit.</b> Offene Pflichtpunkte bzw. Plausibilitätsfragen prüfen.</div>'}<div class="wizardfoot">${back}<button class="btn primary" onclick="finishIntake()">Auftragsdaten erfassen</button></div>`}}
function finishIntake(){show('edit');q('#formTitle').textContent='Neuer Auftrag · Annahme vorbereitet';let f=q('#f');f.elements.process.value=intake.process;f.elements.customer_type.value=intake.customer_kind==='firma'?'Firma':'Privat';f.elements.plate_transfer.value=intake.plate_transfer?'Ja':'Nein';f.elements.need_gbr.value=intake.need_gbr?'Ja':'Nein';f.elements.need_kurzzeit.value=intake.need_kurzzeit?'Ja':'Nein';f.elements.need_ausland_kz.value=intake.need_ausland_kz?'Ja':'Nein';f.elements.need_erhalt.value=intake.need_erhalt?'Ja':'Nein';let docs=[];if(intake.zb1)docs.push('ZB I');if(intake.zb2)docs.push('ZB II');if(intake.hu)docs.push('HU/TÜV');if(intake.coc)docs.push('CoC');if(intake.evb_doc)docs.push('eVB');if(intake.kennzeichen_erhalten)docs.push('Kennzeichen erhalten');if(intake.need_gbr)docs.push('GbR');if(intake.need_kurzzeit)docs.push('Kurzzeitkennzeichen');if(intake.need_ausland_kz)docs.push('Verbleib ausl. Kennzeichen');if(intake.need_erhalt)docs.push('Erhalt Fahrzeugpapiere');f.elements.docs.value=docs.join(', ');recalcFees()}
async function saveIntakeFor(id){if(!id)return;await api('/api/intake',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,data:intake})})}
function newJob(){q('#f').reset();q('#f').elements.id.value='';q('#f').elements.stva_date.value=nextWorkdayClient();q('#f').elements.country.value='Deutschland';q('#formTitle').textContent='Neuer Auftrag';show('edit')}function editJob(id,returnView='all'){let j=jobs.find(x=>x.id===id);if(!j)return;let f=q('#f');for(let e of f.elements)if(e.name&&j[e.name]!=null)e.value=j[e.name];q('#formTitle').textContent='Auftrag #'+id;editReturnView=returnView;show('edit')}
q('#preplanForm').elements.stva_date.addEventListener('change',updatePreplanInfo);
q('#preplanForm').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target).entries());d.country='Deutschland';if(d.process==='Kennzeichenübernahme'){d.plate_transfer='Ja';d.process='Wiederzulassung'}try{let r=await api('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});alert('Termin vorgeplant für '+fmt(r.stva_date)+'.\nStatus: VORGEPLANT');await load();show('all')}catch(x){alert(x.message)}};
q('#f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target).entries()),wanted=d.stva_date;try{let r=await api('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});e.target.elements.id.value=r.id;e.target.elements.stva_date.value=r.stva_date;let msg='Auftrag #'+r.id+' gespeichert.';if(!d.id&&wanted!==r.stva_date)msg+='\n\nDer früheste mögliche StVA-Tag war nicht verfügbar oder bereits mit 8 regulären Aufträgen belegt.\nAutomatisch eingeplant für: '+fmt(r.stva_date);await saveIntakeFor(r.id);alert(msg);await load();editJob(r.id)}catch(x){alert(x.message)}}
async function fillToday(){let t=isoToday();if(!confirm('Freie Plätze 9 und 10 heute mit den ersten Aufträgen des nächsten belegten Tages auffüllen?'))return;try{let r=await api('/api/fill-buffers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:t})});alert(r.moved?r.moved+' Auftrag/Aufträge von '+fmt(r.from_date)+' in die Pufferplätze 9/10 vorgezogen.\nDie Nummerierung wurde automatisch neu aufgebaut.':'Keine Puffer-Auffüllung möglich. Dafür müssen die 8 regulären Plätze heute belegt sein; Kennzeichenübernahmen werden nicht in den Puffer gezogen.');load()}catch(e){alert(e.message)}}
async function quickMove(id){let j=jobs.find(x=>x.id===id),d=prompt('Auf welchen StVA-Tag verschieben? (JJJJ-MM-TT)',j?.stva_date||isoToday());if(!d)return;try{await api('/api/move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,date:d})});await load();renderAll()}catch(e){alert(e.message)}}async function moveCurrent(){let id=+q('#f').elements.id.value;if(!id){alert('Bitte Auftrag zuerst speichern.');return}await quickMove(id);let j=jobs.find(x=>x.id===id);if(j)q('#f').elements.stva_date.value=j.stva_date}
async function saveCurrentSilently(){let f=q('#f'),id=f.elements.id.value;if(!id)return 0;let d=Object.fromEntries(new FormData(f).entries());let r=await api('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});f.elements.id.value=r.id;f.elements.stva_date.value=r.stva_date;return r.id}
async function pdfs(){let id=q('#f').elements.id.value;if(!id){alert('Bitte Auftrag zuerst speichern.');return}try{await saveCurrentSilently();let r=await api('/api/pdfs?id='+id);alert('PDFs erstellt.\nOrdner: '+r.folder+'\n\n'+r.files.join('\n'))}catch(e){alert(e.message)}}async function printPackage(){let id=q('#f').elements.id.value;if(!id){alert('Bitte Auftrag zuerst speichern.');return}window.open('/print?id='+id,'_blank')}async function importExcel(){if(!confirm('Die mitgelieferte Excel-Datei 2026 importieren? Bereits vorhandene Daten können doppelt erscheinen.'))return;try{let r=await api('/api/import');alert(r.count+' belegte Excel-Zeilen importiert.');load();await loadCustomers()}catch(e){alert(e.message)}}
function selectedPrint(){return [...document.querySelectorAll('#printchecks input:checked')].map(x=>x.name)}
function printUrl(){let id=+q('#f').elements.id.value;return '/print?id='+id+'&include='+encodeURIComponent(selectedPrint().join(','))+'&t='+Date.now()}
function applyPrintProfile(){let proc=q('#f').elements.process.value,p=PROCESS_PROFILES[proc]||PROCESS_PROFILES.Zulassung;document.querySelectorAll('#printchecks label').forEach(l=>{let i=l.querySelector('input');if(!i)return;let hide=(i.name==='bank'||i.name==='sepa')&&!p.bank;l.style.display=hide?'none':'';if(hide)i.checked=false})}
async function openPrintCenter(){let id=+q('#f').elements.id.value;if(!id){alert('Bitte Auftrag zuerst speichern.');return}try{await saveCurrentSilently();show('printview');applyPrintProfile();updatePrintPreview()}catch(e){alert('Druckvorschau konnte nicht vorbereitet werden: '+e.message)}}
async function updatePrintPreview(){try{await saveCurrentSilently();q('#printPreview').src=printUrl()}catch(e){alert('Vorschau konnte nicht aktualisiert werden: '+e.message)}}
async function openPrintWindow(){try{await saveCurrentSilently();window.open(printUrl(),'_blank')}catch(e){alert('Druckdatei konnte nicht erstellt werden: '+e.message)}}

function searchAuthority(kind,inputId){let a=(q('#'+inputId).value||'').trim();if(!a){alert('Bitte Stadt oder Landkreis eingeben.');return}let term=kind==='abmeldung'?'i-Kfz Online-Abmeldung':kind==='termin'?'Straßenverkehrsamt Termin online buchen':kind==='auskunft'?'Online-Auskunft Fahrzeugbrief Zulassungsbescheinigung Teil II':'Wunschkennzeichen Kennzeichenreservierung';openExternal('https://www.google.com/search?q='+encodeURIComponent(a+' '+term+' offizielle Seite'))}

loadAppSettings().then(load);
